/* tslint:disable */
/* eslint-disable */
/**
 * ABI version for compatibility checks with npm wrappers.
 */
export function abi_version(): number;
export function normalize_graph_spec_json(json: string): string;
/**
 * Expose the node schema registry as JSON for tooling/UI.
 */
export function get_node_schemas_json(): string;
/**
 * WASM-facing graph runtime with staging and output delta caches.
 *
 * Node-local runtime state lives inside `GraphRuntime` (including per-node state),
 * while this wrapper tracks input staging and output snapshots to avoid crossing
 * the wasm boundary when values are unchanged.
 */
export class WasmGraph {
  free(): void;
  eval_steps(steps: number, dt: number): string;
  load_graph(json_str: string): void;
  /**
   * Evaluate the entire graph and return a JS object (avoids JSON stringify/parse).
   */
  eval_all_js(): any;
  stage_input(path: string, value_json: string, declared_shape_json?: string | null): void;
  /**
   * Step forward multiple times and return only the final outputs/writes.
   * Useful for amortizing JS/WASM boundary cost when ticking many frames.
   */
  eval_steps_js(steps: number, dt: number): any;
  /**
   * Evaluate without serializing to JSON; returns a monotonic output version.
   */
  eval_all_slots(): bigint;
  /**
   * Fetch a float/vec/array output directly as Float32Array (if numeric).
   */
  get_output_f32(node_id: string, output_key: string): Float32Array | undefined;
  set_param_value(node_id: string, key: string, value: any): void;
  /**
   * Stage a float32 vector without JSON, using a shared buffer view.
   */
  stage_input_f32(path: string, data: Float32Array): void;
  /**
   * Clear a staged input by path, removing it from caches and staged inputs.
   */
  clear_input_path(path: string): void;
  /**
   * Clear a staged input by slot index (registered path).
   */
  clear_input_slot(slot_idx: number): void;
  /**
   * Return a full snapshot of outputs/writes (JSON) without re-evaluating.
   */
  get_outputs_full(): any;
  /**
   * Batch fetch the default "out" port for many nodes as a Float32Array (scalars only; non-scalars -> NaN).
   */
  get_outputs_batch(nodes: any): Float32Array;
  /**
   * Return only outputs that changed since the provided version token.
   */
  get_outputs_delta(since_version: bigint): any;
  stage_input_value(path: string, value: any, declared_shape: any): void;
  /**
   * Batch-stage many scalar/vector inputs in one call (paths[i] -> values[i]).
   */
  stage_inputs_batch(paths: any, values: Float32Array): void;
  /**
   * Stage inputs by pre-prepared slots (no path parse, reuse declared).
   */
  stage_inputs_slots(indices: Uint32Array, values: Float32Array): void;
  /**
   * Pre-allocate slots with declared shapes to enable slot staging.
   */
  prepare_input_slots(indices: Uint32Array, declared: any): void;
  /**
   * Evaluate and return only outputs that changed since the provided version token in a single crossing.
   */
  eval_all_slots_delta(since_version: bigint): any;
  /**
   * Register paths once and reuse their indices for faster staging.
   */
  register_input_paths(paths: any): Uint32Array;
  /**
   * Stage inputs by index using previously registered paths.
   */
  stage_inputs_indices(indices: Uint32Array, values: Float32Array): void;
  constructor();
  step(dt: number): void;
  /**
   * Evaluate the entire graph and return all outputs as JSON.
   * Returned JSON shape:
   * {
   *   "nodes": { [nodeId]: { [outputKey]: { "value": ValueJSON, "shape": ShapeJSON } } },
   *   "writes": [ { "path": string, "value": ValueJSON, "shape": ShapeJSON }, ... ]
   * }
   */
  eval_all(): string;
  set_time(t: number): void;
  /**
   * Set a param on a node (e.g., key="value" with float/bool/vec3 JSON).
   *
   * Structural parameter edits (e.g., adjusting Split sizes) invalidate the
   * cached execution plan so the next evaluation rebuilds layouts safely.
   */
  set_param(node_id: string, key: string, json_value: string): void;
}

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
  readonly memory: WebAssembly.Memory;
  readonly __wbg_wasmgraph_free: (a: number, b: number) => void;
  readonly abi_version: () => number;
  readonly get_node_schemas_json: () => [number, number];
  readonly normalize_graph_spec_json: (a: number, b: number) => [number, number, number, number];
  readonly wasmgraph_clear_input_path: (a: number, b: number, c: number) => [number, number];
  readonly wasmgraph_clear_input_slot: (a: number, b: number) => [number, number];
  readonly wasmgraph_eval_all: (a: number) => [number, number, number, number];
  readonly wasmgraph_eval_all_js: (a: number) => [number, number, number];
  readonly wasmgraph_eval_all_slots: (a: number) => [bigint, number, number];
  readonly wasmgraph_eval_all_slots_delta: (a: number, b: bigint) => [number, number, number];
  readonly wasmgraph_eval_steps: (a: number, b: number, c: number) => [number, number, number, number];
  readonly wasmgraph_eval_steps_js: (a: number, b: number, c: number) => [number, number, number];
  readonly wasmgraph_get_output_f32: (a: number, b: number, c: number, d: number, e: number) => any;
  readonly wasmgraph_get_outputs_batch: (a: number, b: any) => [number, number, number];
  readonly wasmgraph_get_outputs_delta: (a: number, b: bigint) => [number, number, number];
  readonly wasmgraph_get_outputs_full: (a: number) => [number, number, number];
  readonly wasmgraph_load_graph: (a: number, b: number, c: number) => [number, number];
  readonly wasmgraph_new: () => number;
  readonly wasmgraph_prepare_input_slots: (a: number, b: any, c: any) => [number, number];
  readonly wasmgraph_register_input_paths: (a: number, b: any) => [number, number, number];
  readonly wasmgraph_set_param: (a: number, b: number, c: number, d: number, e: number, f: number, g: number) => [number, number];
  readonly wasmgraph_set_param_value: (a: number, b: number, c: number, d: number, e: number, f: any) => [number, number];
  readonly wasmgraph_set_time: (a: number, b: number) => void;
  readonly wasmgraph_stage_input: (a: number, b: number, c: number, d: number, e: number, f: number, g: number) => [number, number];
  readonly wasmgraph_stage_input_f32: (a: number, b: number, c: number, d: any) => [number, number];
  readonly wasmgraph_stage_input_value: (a: number, b: number, c: number, d: any, e: any) => [number, number];
  readonly wasmgraph_stage_inputs_batch: (a: number, b: any, c: any) => [number, number];
  readonly wasmgraph_stage_inputs_indices: (a: number, b: any, c: any) => [number, number];
  readonly wasmgraph_stage_inputs_slots: (a: number, b: any, c: any) => [number, number];
  readonly wasmgraph_step: (a: number, b: number) => void;
  readonly __wbindgen_malloc: (a: number, b: number) => number;
  readonly __wbindgen_realloc: (a: number, b: number, c: number, d: number) => number;
  readonly __wbindgen_exn_store: (a: number) => void;
  readonly __externref_table_alloc: () => number;
  readonly __wbindgen_export_4: WebAssembly.Table;
  readonly __externref_table_dealloc: (a: number) => void;
  readonly __wbindgen_free: (a: number, b: number, c: number) => void;
  readonly __wbindgen_start: () => void;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;
/**
* Instantiates the given `module`, which can either be bytes or
* a precompiled `WebAssembly.Module`.
*
* @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
*
* @returns {InitOutput}
*/
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
* If `module_or_path` is {RequestInfo} or {URL}, makes a request and
* for everything else, calls `WebAssembly.instantiate` directly.
*
* @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
*
* @returns {Promise<InitOutput>}
*/
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
